from collections import defaultdict

class Solution:
    def mergeSimilarItems(self, items1: list[list[int]], items2: list[list[int]]) -> list[list[int]]:
        weights = defaultdict(int)
        for v, w in items1 + items2:
            weights[v] += w
        return [[v, weights[v]] for v in sorted(weights)]

class Solution {
public:
    std::vector<std::vector<int>> mergeSimilarItems(std::vector<std::vector<int>>& items1, std::vector<std::vector<int>>& items2) {
        std::map<int, int> weights;
        for (const auto& it : items1) weights[it[0]] += it[1];
        for (const auto& it : items2) weights[it[0]] += it[1];
        std::vector<std::vector<int>> ans;
        for (auto& [v, w] : weights) ans.push_back({v, w});
        return ans;
    }
};

class Solution {
    public java.util.List<java.util.List<Integer>> mergeSimilarItems(int[][] items1, int[][] items2) {
        java.util.Map<Integer, Integer> weights = new java.util.TreeMap<>();
        for (int[] it : items1) weights.put(it[0], weights.getOrDefault(it[0], 0) + it[1]);
        for (int[] it : items2) weights.put(it[0], weights.getOrDefault(it[0], 0) + it[1]);
        java.util.List<java.util.List<Integer>> ans = new java.util.ArrayList<>();
        for (var entry : weights.entrySet()) {
            ans.add(java.util.List.of(entry.getKey(), entry.getValue()));
        }
        return ans;
    }
}

var mergeSimilarItems = function(items1, items2) {
    const map = new Map();
    for (const [v, w] of [...items1, ...items2]) {
        map.set(v, (map.get(v) || 0) + w);
    }
    const sortedKeys = Array.from(map.keys()).sort((a, b) => a - b);
    return sortedKeys.map(v => [v, map.get(v)]);
};
